import json
from datetime import date
from pathlib import Path

DATA = Path("expenses.json")

def load():
    if not DATA.exists():
        return []
    with DATA.open(encoding="utf-8") as file:
        return json.load(file)

def save(expenses):
    with DATA.open("w", encoding="utf-8") as file:
        json.dump(expenses, file, indent=2)

def add_expense(expenses):
    category = input("Category: ").strip() or "uncategorised"
    while True:
        try:
            amount = float(input("Amount: "))
            break
        except ValueError:
            print("Enter a number such as 12.50")
    note = input("Note: ").strip()
    expenses.append({
        "date": date.today().isoformat(),
        "category": category,
        "amount": amount,
        "note": note
    })
    save(expenses)
    print("Expense saved.")

def list_expenses(expenses):
    if not expenses:
        print("No expenses yet.")
        return
    for item in expenses:
        print(f"{item['date']}  {item['category']:<12}  {item['amount']:>8.2f}  {item['note']}")
    print(f"Total: {sum(item['amount'] for item in expenses):.2f}")

def main():
    expenses = load()
    while True:
        print("\n1) Add  2) List  3) Quit")
        choice = input("Choose: ").strip()
        if choice == "1":
            add_expense(expenses)
        elif choice == "2":
            listing = expenses
            category = input("Filter category (blank for all): ").strip().lower()
            if category:
                listing = [item for item in expenses if item["category"].lower() == category]
            list_expenses(listing)
        elif choice == "3":
            break
        else:
            print("Choose 1, 2, or 3.")

if __name__ == "__main__":
    main()

def total_expenses(expenses, category=None):
    if category is None:
        return sum(item["amount"] for item in expenses)
    return sum(item["amount"] for item in expenses if item["category"] == category)

assert total_expenses([{"amount": 2.0}, {"amount": 3.5}]) == 5.5
assert total_expenses([{"amount": 2.0, "category": "food"}], "food") == 2.0
